export const meta = {
  name: 'chain-AAAB',
  description: 'RUN-1 stage 1: B2+B3, F2, F3, F4 - fix then verify each ticket',
  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}
const VERDICT = { type: 'object', properties: {
  ticket: { type: 'string' }, passed: { type: 'boolean' }, why: { type: 'string' },
  evidence: { type: 'string', description: 'the check that ran and its output' },
  files: { type: 'array', items: { type: 'string' } },
  parked: { type: 'object', properties: { question: {type:'string'}, header: {type:'string', maxLength: 8},
    options: {type:'array', minItems: 2, maxItems: 4, items: {type:'object', properties: {label:{type:'string'}, does:{type:'string'}, hurts:{type:'string'}}}},
    recommended: {type:'string'}, default: {type:'string'}, reason: {enum: ['taste','fact','conflict']},
    genuine: {type:'boolean'}, gated: {type:'string'}, files: {type:'array', minItems: 1, items: {type:'string'}},
    done: {type:'string'}, stop: {enum: ['none','destructive','security','outside','scope','repro']} },
    required: ['question','header','options','default','reason','genuine','gated','files','stop'] },
}, required: ['ticket', 'passed', 'why', 'evidence', 'files'] }
const { header, verify, items } = args
return await pipeline(items,
  it => agent(`${header}\n\nYOUR ITEM ONLY:\n${it.body}\n\nImplement it, run python -m pytest -q, and report what you changed, the test output, any Ruling:, and PARKED:/STOP: if applicable.`,
    { label: `AAAB fix:${it.id}`, phase: 'Fix' }),
  (report, it) => agent(`${header}\n\nYou are the VERIFIER for item ${it.id} (files: ${it.files}).\n${it.body}\n\n${verify}\n\nFixer's report:\n${report}\n\nReturn a VERDICT with ticket "${it.id}". passed=true only if a check you ran shows the behaviour; put that check and its output in evidence.`,
    { label: `AAAB verify:${it.id}`, phase: 'Verify', schema: VERDICT }),
)

